/**
 * Writes src/staff-assistant/client.generated.ts from client.ts (Node strips the types of this
 * script itself). `--check` fails when the generated file is out of date.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { compileClients } from "../src/client/build.ts";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT = `${ROOT}src/staff-assistant/client.generated.ts`;
const js = compileClients([readFileSync(`${ROOT}src/staff-assistant/client.ts`, "utf8")]);
const text = `// GENERATED by scripts/build-staff-client.ts from src/staff-assistant/client.ts — run \`pnpm --filter @psi/ui build:staff-client\`, never edit.
/** The staff assistant's page script, inlined once beside the panel. */
export const STAFF_ASSISTANT_JS: string = ${JSON.stringify(js)};
`;

if (process.argv.includes("--check")) {
	if (readFileSync(OUT, "utf8") !== text) {
		console.error(
			"client.generated.ts is out of date: run `pnpm --filter @psi/ui build:staff-client`",
		);
		process.exit(1);
	}
	console.log("staff assistant bundle up to date");
} else {
	writeFileSync(OUT, text);
	console.log(`staff assistant ${text.length} B → src/staff-assistant/client.generated.ts`);
}
